static Optional<Integer> parseIntSafe(String s) {
    try {
        return Optional.of(Integer.parseInt(s));
    } catch (NumberFormatException e) {
        return Optional.empty();
    }
}

public static void main(String[] args) {
    List<String> inputs = List.of("10", "abc", "20", "xyz", "5");
    int sum = inputs.stream()
            .map(Exercise23_OptionalInStreamPipeline::parseIntSafe)
            .flatMap(Optional::stream)
            .mapToInt(Integer::intValue)
            .sum();
    System.out.println("Suma poprawnych liczb: " + sum);
}

