class Account {
    double balance;
    Account(double balance) { this.balance = balance; }
    Optional<Account> withdraw(double amount) {
        if (balance - amount < 0) return Optional.empty();
        return Optional.of(new Account(balance - amount));
    }
}

Optional<Account> result = Optional.of(new Account(100))
        .flatMap(acc -> acc.withdraw(30))
        .flatMap(acc -> acc.withdraw(50))
        .flatMap(acc -> acc.withdraw(40)); // 100-30-50=20, 20-40 < 0 -> empty

result.ifPresentOrElse(
    acc -> System.out.println("Koncowe saldo: " + acc.balance),
    () -> System.out.println("Wyplata nieudana - niewystarczajace srodki")
);

class Kierownik {
    String imie;
    Kierownik(String imie) { this.imie = imie; }
    Optional<String> getImie() { return Optional.ofNullable(imie); }
}
class Dzial {
    Optional<Kierownik> kierownik;
    Dzial(Optional<Kierownik> kierownik) { this.kierownik = kierownik; }
    Optional<Kierownik> getKierownik() { return kierownik; }
}
class Firma {
    Optional<Dzial> dzial;
    Firma(Optional<Dzial> dzial) { this.dzial = dzial; }
    Optional<Dzial> getDzial() { return dzial; }
}

Firma pelne = new Firma(Optional.of(new Dzial(Optional.of(new Kierownik("Anna")))));
Firma brakDzialu = new Firma(Optional.empty());
Firma brakKierownika = new Firma(Optional.of(new Dzial(Optional.empty())));

for (Firma f : List.of(pelne, brakDzialu, brakKierownika)) {
    String imie = f.getDzial()
            .flatMap(Dzial::getKierownik)
            .flatMap(Kierownik::getImie)
            .orElse("Brak danych");
    System.out.println(imie);
}

static Map<String, List<Integer>> groupScores = Map.of(
    "A", List.of(80, 90, 70), "B", List.of(), "C", List.of(60)
);

static Optional<Double> getAverageScore(String group) {
    List<Integer> scores = groupScores.get(group);
    if (scores == null || scores.isEmpty()) return Optional.empty();
    OptionalDouble avg = scores.stream().mapToInt(Integer::intValue).average();
    return avg.isPresent() ? Optional.of(avg.getAsDouble()) : Optional.empty();
}

public static void main(String[] args) {
    for (String group : List.of("A", "B", "D")) {
        System.out.println(group + ": " + getAverageScore(group).map(String::valueOf).orElse("brak danych"));
    }
}

